// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address attacker, uint256 burnAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != c.owner());
        vm.prank(attacker);
        try c.owned() {} catch {}
        vm.prank(c.owner());
        c.mintToken(c.owner(), burnAmount);
        vm.prank(c.owner());
        c.burn(burnAmount);
        assertEq(c.owner(), address(this));
    }
}
